};
if (ecartes.length) {
  avertissements.push({ type: 'contradiction_modele_ecartee', detail: `${ecartes.length} vom KI-Assistenten gemeldete(r) Widerspruch/Widersprüche verworfen: Sie stützen sich auf keinen Fakt der Akte.` });
}
if (iaExecutee) {
  heriter('extraction', extraction);
  heriter('comparaison', comparaison);
}
if (regles.length && !modele.length && comparaison.texte) {
  avertissements.push({ type: 'modele_a_rate', detail: 'Der KI-Assistent hat keinen Widerspruch gemeldet; die Widersprüche stammen aus den Kontrollregeln.' });
}

return [
  {
    json: {
      texte: lignes.join('\n'),
      contradictions,
      sources: [...new Set(contradictions.flatMap((c) => c.sources).concat(SRC_LETTRE))],
      alertes: contradictions.map((c) => ({ type: 'contradiction', message: c.description })),
      avertissements,
      nb_regles: regles.length,
      nb_modele: deModele.length,
      ia_executee: iaExecutee,
      contradictions_modele: deModele,
      ecartees_modele: ecartes.length,
      lettre_ref: lettre.ref,
      modele: comparaison.modele ?? extraction.modele ?? null,
      prompt_versions: iaExecutee ? `extraire_faits@${extraction.prompt_version ?? '?'}+comparer@${comparaison.prompt_version ?? '?'}+regles@1.0.0` : 'regles@1.0.0',
    },
  },
];

// Dokument prüfen – ZUSÄTZLICHE ANALYSE (Hintergrundaufgabe): was der KI-Assistent zu den Kontrollregeln hinzufügt.
// Die Regeln und der bereits gelieferte Text ändern sich nicht; nur die Anmerkungen kommen hinzu, als « zu prüfen » gekennzeichnet.
const f = $('Regeln und Zusammenführung').first().json;
const tache = $('Analyseaufgabe erstellen').first().json.id;
const lu = (nom) => {
  try {
    return $(nom).first().json ?? {};
  } catch {
    return {};
  }
};
const echecIA = !lu('Verfassen (Extraktion)').texte && !lu('Verfassen (Vergleich)').texte; // beide Schritte sind fehlgeschlagen
const remarques = (f.contradictions_modele ?? []).map((c) => ({
  type: c.type, gravite: c.gravite, description: c.description, element_lettre: c.element_lettre, element_source: c.element_source, sources: c.sources,
}));
const c = $('Schreiben wählen').first().json;
return [
  {
    json: {
      task_id: tache,
      statut: echecIA ? 'termine_avec_erreurs' : 'termine',
      resultat: {
        remarques,
        alertes: remarques.map((r) => ({ type: 'contradiction', message: r.description })),
        avertissements: f.avertissements ?? [],
        ecartees: f.ecartees_modele ?? 0,
        indisponible: echecIA,
        modele: f.modele ?? null,
      },
      evenement_journal: {
        evenement: 'analyse_complementaire',
        patient_id: c.patient.patient_id,
        mode: 'a',
        action: 'verifier_document',
        prompt_id: 'verifier_document',
        prompt_version: f.prompt_versions,
        modele: f.modele,
        details: { tache_id: tache, remarques_modele: remarques.length, ecartees: f.ecartees_modele ?? 0, indisponible: echecIA },
      },
    },
  },
];

// Dokument prüfen – SOFORTIGE ANTWORT: der Bericht der Kontrollregeln (Code, ohne KI), einem Entwurf zugeordnet.
// Die zusätzliche Analyse des KI-Assistenten läuft, falls aktiviert, anschließend als Hintergrundaufgabe weiter (tache_id).
const f = $('Nur Regeln').first().json;
const b = $('Prüfentwurf erstellen').first().json;
const c = $('Schreiben wählen').first().json;
let tache = null;
try {
  tache = $('Analyseaufgabe erstellen').first().json.id ?? null;
} catch {
  /* KI-Analyse deaktiviert: keine Aufgabe */
}
return [
  {
    json: {
      reponse: {
        brouillon_id: b.id,
        texte: f.texte,
        sources: f.sources,
        alertes: f.alertes,
        avertissements: f.avertissements,
        retirees: [],
        analyse: tache ? { statut: 'en_cours', tache_id: tache } : { statut: 'desactivee' },
      },
      evenement_journal: {
        evenement: 'verification',
        patient_id: c.patient.patient_id,
        mode: 'a',
        action: 'verifier_document',
        prompt_id: 'verifier_document',
        prompt_version: f.prompt_versions,
        details: { brouillon_id: b.id, lettre: f.lettre_ref, contradictions_regles: f.nb_regles, analyse_ia: tache ? 'en_cours' : 'desactivee', tache_id: tache },
      },
    },
  },
];

// Sitzungsprüfung – das « Bearer »-Token im Authorization-Header (43 URL-sichere Zeichen) wird gehasht (SHA-256): Nur der Hash steht in der Datenbank.
const entetes = $input.first().json?.headers ?? {};
const m = String(entetes.authorization ?? '').match(/^Bearer ([A-Za-z0-9_-]{43})$/);
if (!m) return [{ json: { hash: '' } }];
return [{ json: { hash: require('crypto').createHash('sha256').update(m[1]).digest('hex') } }];

// Sitzungsprüfung – Ergebnis: eine identifizierte Pflegekraft (Sitzung offen, nicht abgelaufen, Konto aktiv) oder nichts.
const r = $input.first().json ?? {};
if (!r.identifiant) return [{ json: { ok: false } }];
return [{ json: { ok: true, soignant: { identifiant: r.identifiant, nom: r.nom }, jeton_hash: r.jeton_hash } }];
